const input = $input.first().json || {};
let payload = input.payload;
if (typeof payload === 'string') { try { payload = JSON.parse(payload); } catch { throw new Error('payload deve ser um JSON válido.'); } }
if (!payload || typeof payload !== 'object' || Array.isArray(payload)) throw new Error('payload obrigatório.');
for (const campo of ['p_nome','p_empresa','p_servico','p_descricao']) {
  if (!String(payload[campo] || '').trim()) throw new Error('Campo obrigatório ausente: ' + campo);
}
if (!String(payload.p_categoria || '').trim()) payload.p_categoria = String(payload.p_servico).trim();
if (payload.p_autoriza_publicacao !== true) throw new Error('A carga exige autorização de publicação explícita.');
return [{ json: { payload } }];

const raw = $input.first().json?.data ?? $input.first().json;
let data = raw;
if (typeof raw === 'string') { try { data = JSON.parse(raw); } catch { data = []; } }
const item = Array.isArray(data) ? data[0] : data;
if (!item?.servico_id) throw new Error('A importação não retornou o serviço para indexação.');
const payload = $('Validar carga controlada').first().json.payload;
const schema = {
  type: 'object', additionalProperties: false,
  properties: {
    descricao_busca: { type: 'string' },
    problemas_atendidos: { type: 'array', items: { type: 'string' }, maxItems: 12 }
  },
  required: ['descricao_busca', 'problemas_atendidos']
};
const body = {
  model: 'google/gemini-2.5-flash', temperature: 0, max_tokens: 900,
  reasoning: { enabled: false },
  response_format: { type: 'json_schema', json_schema: { name: 'elo_indice_servico', strict: true, schema } },
  messages: [
    { role: 'system', content: [
      'Prepare um texto curto para pesquisa de uma oferta de serviço da Elo Connect.',
      'Use exclusivamente os fatos fornecidos. Não invente serviços, especialidades, resultados, localização ou qualificações.',
      'A descrição deve explicar o serviço e os problemas explicitamente atendidos em linguagem natural.',
      'Os problemas atendidos devem ser derivações diretas dos dados recebidos, sem ampliar a atuação da empresa.'
    ].join('\n') },
    { role: 'user', content: JSON.stringify({
      empresa: payload.p_empresa,
      servico: payload.p_servico,
      categoria_informada: payload.p_categoria,
      descricao: payload.p_descricao,
      problemas_resolvidos: payload.p_problemas_resolvidos || '',
      especialidades: payload.p_especialidades || []
    }) }
  ]
};
return [{ json: { item, payload, body } }];

const preparado = $('Preparar embedding do serviço').first().json;
const raw = $input.first().json?.data ?? $input.first().json;
let data = raw;
if (typeof raw === 'string') { try { data = JSON.parse(raw); } catch { data = []; } }
const atualizado = Array.isArray(data) ? data[0] : data;
return [{ json: {
  cadastro_id: preparado.cadastro_id,
  servico_id: preparado.servico_id,
  status: atualizado?.status_indexacao || 'indexado',
  indexed_at: atualizado?.indexed_at || null
} }];

const clean = (value) => String(value || '').trim();
const parse = (value) => {
  if (value && typeof value === 'object') return value;
  const text = clean(value).replace(/```json|```/g, '').trim();
  try { return JSON.parse(text); } catch {}
  const match = text.match(/\{[\s\S]*\}/);
  if (match) { try { return JSON.parse(match[0]); } catch {} }
  return {};
};
const preparado = $('Preparar enriquecimento de busca').first().json;
const payload = preparado.payload;
const resposta = parse($input.first().json.choices?.[0]?.message?.content);
const base = [
  'Empresa: ' + clean(payload.p_empresa),
  'Serviço: ' + clean(payload.p_servico),
  'Categoria informada: ' + clean(payload.p_categoria),
  'Descrição original: ' + clean(payload.p_descricao),
  payload.p_problemas_resolvidos ? 'Problemas informados: ' + clean(payload.p_problemas_resolvidos) : '',
  Array.isArray(payload.p_especialidades) && payload.p_especialidades.length
    ? 'Especialidades informadas: ' + payload.p_especialidades.map(clean).filter(Boolean).join(', ') : ''
].filter(Boolean);
if (clean(resposta.descricao_busca)) base.push('Descrição pesquisável: ' + clean(resposta.descricao_busca));
if (Array.isArray(resposta.problemas_atendidos) && resposta.problemas_atendidos.length) {
  base.push('Problemas atendidos: ' + resposta.problemas_atendidos.map(clean).filter(Boolean).join(', '));
}
return [{ json: {
  cadastro_id: preparado.item.cadastro_id,
  servico_id: preparado.item.servico_id,
  descricao_busca: base.join('\n')
} }];
